{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine, a lipophilic dihydropyridine, has a mean systemic availability of 16.5% in healthy volunteers after oral administration, providing direct human evidence of F below the 20% threshold; its lipophilicity and extensive first-pass liability support a low-F phenotype for the similarly lipophilic, large query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, a lipophilic opioid, shows absolute oral bioavailability of 18% in healthy subjects, another direct human measurement below 20% that supports the low-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib, a poorly soluble compound, has an absolute oral bioavailability of only 13.9% in the fed state, demonstrating that solubility/absorption limitations can drive F below the 20% threshold in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nifedipine has oral bioavailability of 45-53% in humans, which is above the threshold; however, its much lower molecular weight and less extreme lipophilicity limit transferability to the large polyprenyl quinone query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Soraprazan shows 50% oral bioavailability in healthy volunteers, but it is a smaller, more soluble molecule and does not reflect the absorption limitations expected for the query's long isoprenoid chain.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, highly lipophilic polyprenyl benzoquinone (CoQ10-like) with very low aqueous solubility, which limits oral absorption. Direct human low-F analogues (isradipine, pentazocine, fed-state rigosertib) support F < 20%, while high-F analogues are smaller, more soluble molecules and are outweighed by the query's extreme physicochemical properties. Prediction: low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule; all evidence is from structurally distinct small-molecule drugs.",
    "The query's bioavailability is likely formulation-dependent; no formulation or dose is specified.",
    "The mechanism of low F in the cited low-F analogues (first-pass metabolism) may differ from the query's absorption-limited disposition."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

